/// <summary>
/// Helper class to perform Sales quota operations on Sales lines CDS entity
/// </summary>
internal final class METSalesOrderCDSLineEntityQuotaHelper 
{
    AgreementLine       agreementLine;


}

Method.Source:
    /// <summary>
    /// Method used to apply quantity and value based quota
    /// CB_202 SalesQuota changes by Akshay
    /// </summary>
    /// <param name = "_salesOrderLineV2Entity">Sales order line v2 entity reference</param>
    /// <returns>AgreementLine reference</returns>
    public static AgreementLine applyQuotaOnSalesLine(SalesOrderLineV2Entity    _salesOrderLineV2Entity)
    {
        SalesAgreementHeader        salesAgreementHeader;
        SalesTable                  salesTable;
        METSalesTable               metSalesTable;
        SalesLine                   salesLineUpdate;
        TransDate                   receiptDate;
        ReasonCode                  reasonCode;
        AgreementLine               agreementLine;

        salesTable = SalesTable::find(_salesOrderLineV2Entity.SalesOrderNumber, true);
        metSalesTable = METSalesTable::findByRefRecId(salesTable.recId);

        receiptDate = salesTable.receiptDate();

        _salesOrderLineV2Entity.METOrderedQuantity = _salesOrderLineV2Entity.OrderedSalesQuantity;

        select firstonly agreementLine
                where agreementLine.ItemId == _salesOrderLineV2Entity.ItemNumber
            join salesAgreementHeader
                where salesAgreementHeader.RecId == agreementLine.Agreement                 &&
                    salesAgreementHeader.AgreementState == AgreementState::Effective        &&
                    salesAgreementHeader.CustAccount    == salesTable.CustAccount           &&
                    salesAgreementHeader.DefaultAgreementLineEffectiveDate <= receiptDate   &&
                    salesAgreementHeader.DefaultAgreementLineExpirationDate >= receiptDate;

        reasonCode = AgreementClassification::find(salesAgreementHeader.AgreementClassification).METCustReason;

        salesLineUpdate = SalesLine::findInventTransId(_salesOrderLineV2Entity.InventoryLotId);

        if (agreementLine.agreementHeader().DefaultAgreementLineType == CommitmentType::ProductVolume)
        {
            Amount      remainingAmountInAgreementLine = agreementLine.METgetAgreementLineRemainingAmount();
            
            if (remainingAmountInAgreementLine < _salesOrderLineV2Entity.SalesPrice)
            {
                _salesOrderLineV2Entity.SalesOrderLineStatus    = SalesStatus::Canceled;
                _salesOrderLineV2Entity.METReducedQuantity      = _salesOrderLineV2Entity.OrderedSalesQuantity;
                _salesOrderLineV2Entity.METReasonId             = reasonCode;
            }
            else if (salesLineUpdate.RecId != 0 && _salesOrderLineV2Entity.LineAmount > remainingAmountInAgreementLine && _salesOrderLineV2Entity.SalesPrice != 0)
            {
                int     reducedQty = remainingAmountInAgreementLine / _salesOrderLineV2Entity.SalesPrice;

                _salesOrderLineV2Entity.OrderedSalesQuantity    = reducedQty;
                _salesOrderLineV2Entity.SalesPrice              = _salesOrderLineV2Entity.SalesPrice;
                _salesOrderLineV2Entity.LineAmount              = _salesOrderLineV2Entity.SalesPrice * reducedQty;
                _salesOrderLineV2Entity.METReasonId             = reasonCode;
                _salesOrderLineV2Entity.METReducedQuantity      = _salesOrderLineV2Entity.METOrderedQuantity - _salesOrderLineV2Entity.OrderedSalesQuantity;
            }
        }
        else if(agreementLine.agreementHeader().DefaultAgreementLineType == CommitmentType::ProductQuantity)
        {
            Qty qtyRemainInAgreementLine = agreementLine.METgetAgreementLineRemainingInventQty();
            
            if (salesLineUpdate.MatchingAgreementLine)
            {
                if (salesLineUpdate.QtyOrdered >= _salesOrderLineV2Entity.OrderedSalesQuantity)
                {
                    _salesOrderLineV2Entity.METReducedQuantity      = _salesOrderLineV2Entity.OrderedSalesQuantity;
                    _salesOrderLineV2Entity.METReasonId             = reasonCode;
                }
                else if (salesLineUpdate.QtyOrdered <= _salesOrderLineV2Entity.OrderedSalesQuantity)
                {
                    Qty     leftOverQty = qtyRemainInAgreementLine + salesLineUpdate.QtyOrdered;

                    if (leftOverQty <= _salesOrderLineV2Entity.OrderedSalesQuantity)
                    {
                        _salesOrderLineV2Entity.OrderedSalesQuantity    = leftOverQty;
                        _salesOrderLineV2Entity.METReasonId             = reasonCode;
                        _salesOrderLineV2Entity.METReducedQuantity      = _salesOrderLineV2Entity.METOrderedQuantity - _salesOrderLineV2Entity.OrderedSalesQuantity;
                    }
                }

                return agreementLine;
            }
            if (qtyRemainInAgreementLine == 0)
            {
                _salesOrderLineV2Entity.SalesOrderLineStatus    = SalesStatus::Canceled;
                _salesOrderLineV2Entity.METReducedQuantity      = _salesOrderLineV2Entity.OrderedSalesQuantity;
                _salesOrderLineV2Entity.METReasonId             = reasonCode;
            }
            else if (salesLineUpdate.RecId == 0 && qtyRemainInAgreementLine != 0)
            {
                _salesOrderLineV2Entity.METReducedQuantity      = _salesOrderLineV2Entity.METOrderedQuantity - _salesOrderLineV2Entity.OrderedSalesQuantity;
                _salesOrderLineV2Entity.METReasonId             = reasonCode;

            }
            else if (qtyRemainInAgreementLine != 0 && qtyRemainInAgreementLine < _salesOrderLineV2Entity.OrderedSalesQuantity)
            {
                _salesOrderLineV2Entity.OrderedSalesQuantity    = qtyRemainInAgreementLine;
                _salesOrderLineV2Entity.METReasonId             = reasonCode;
                _salesOrderLineV2Entity.METReducedQuantity      = _salesOrderLineV2Entity.METOrderedQuantity - _salesOrderLineV2Entity.OrderedSalesQuantity;
            }
        }

        return agreementLine;
    }

    /// <summary>
    /// updates the ordered quantity based on the sales agreement line fulfillment
    /// </summary>
    /// <param name = "_salesOrderLineV2Entity">Sales order line V2 entity buffer</param>
    /// <returns>Boolean value</returns>
    public boolean updateQuotaQty(SalesOrderLineV2Entity _salesOrderLineV2Entity)
    {
        boolean quotaUpdated = true;
        AgreementLine matchingAgreementLine;
        SalesTable salesTable = SalesTable::find(_salesOrderLineV2Entity.SalesOrderNumber);
        
        if(salesTable.MatchingAgreement)
        {
            SalesLine salesLine = SalesLine::findInventTransId(_salesOrderLineV2Entity.InventoryLotId);

            if(salesLine)
            {
                matchingAgreementLine = this.getAgreementLineForSalesLine(salesLine);

                if(salesLine.MatchingAgreementLine == matchingAgreementLine.RecId)
                {
                    if(!this.validateRequestedShipDateWithAgreementLine(matchingAgreementLine, _salesOrderLineV2Entity.RequestedShippingDate))
                    {
                        salesLine.unLinkAgreementLine(true);
                        return false;
                    }
                }
            }
            else
            {
                salesLine = this.createSalesLineTmp(_salesOrderLineV2Entity);
                matchingAgreementLine = this.getAgreementLineForSalesLine(salesLine);
            }

            if(!matchingAgreementLine)
            {
                return false;
            }

            if(matchingAgreementLine.agreementHeader().DefaultAgreementLineType == CommitmentType::ProductQuantity)
            {
                
                Qty qtyRemainInAgreementLine = this.getAgreementLineRemainingInventQty(matchingAgreementLine);

                if(qtyRemainInAgreementLine < _salesOrderLineV2Entity.OrderedSalesQuantity)
                {
                    _salesOrderLineV2Entity.OrderedSalesQuantity = qtyRemainInAgreementLine;
                    _salesOrderLineV2Entity.METReasonId = METCustParameters::Find().SalesQuotaReasonId;
                }
            }
        }

        return quotaUpdated;
    }

    /// <summary>
    /// Gets the remaining qty to be fulfilled by sales order line for given agreement line
    /// </summary>
    /// <param name = "_agreementLine">Agreement line</param>
    /// <returns>Qty to be fulfilled</returns>
    public Qty getAgreementLineRemainingInventQty(AgreementLine _agreementLine)
    {
        SalesQty                        salesQtyRemainAgreement;
        #AgreementsRemains
        container fulfillmentValues = AgreementLine::calculateFulfillmentForLine(_agreementLine);

        salesQtyRemainAgreement = conPeek(fulfillmentValues, #RemainingIndex);

        return salesQtyRemainAgreement;
    }

/// <summary>
/// Gets the agreement line best matched for sales order line. If sales order line is already having the matching agreement line the return the same.
/// </summary>
/// <param name = "_salesLine">Sales line</param>
/// <returns>Best matched agreement line</returns>
public AgreementLine getAgreementLineForSalesLine(SalesLine _salesLine)
{
    AgreementLine agreementLineLocal;
    if(_salesLine.MatchingAgreementLine)
    {
        agreementLineLocal = AgreementLine::find(_salesLine.MatchingAgreementLine);
    }
    else
    {
        AgreementAutolinkHelperSalesLine agreementAutoLinkHelper = new AgreementAutolinkHelperSalesLine();
        agreementLineLocal = agreementAutoLinkHelper.findLineForAutoMatch(_salesLine, false);
    }
   
    return agreementLineLocal;
}

   /// <summary>
    /// Calculates inventory quantity from sales quantity.
   /// </summary>
   /// <param name = "_itemId">ItemId reference</param>
   /// <param name = "_inventDimId">InventDimId reference</param>
   /// <param name = "_inventUnit">Invent unit reference</param>
   /// <param name = "_salesUnit">Sales unit reference</param>
   /// <param name = "_salesQty">Sales qty reference</param>
   /// <returns>Invent qty</returns>
    public InventQty calculateInventoryQty(ItemId               _itemId,
                                           InventDimId          _inventDimId,
                                           UnitOfMeasureSymbol  _inventUnit,
                                           UnitOfMeasureSymbol  _salesUnit,
                                           SalesQty             _salesQty
                                            )
    {
        InventQty   orderedQty;

        if (_inventUnit  == _salesUnit)
        {
            orderedQty  = _salesQty;
        }
        else
        {
            orderedQty  = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_itemId, _inventDimId, _salesQty, _salesUnit, _inventUnit, NoYes::Yes);
            orderedQty  = decRound(orderedQty, InventTable::inventDecimals(_itemId));
        }

        return orderedQty;
    }

    /// <summary>
    /// Validates the sales line and agreement line based on requested ship date
    /// </summary>
    /// <param name = "_agreementLine">Agreement line</param>
    /// <param name = "_shipRequested">Requested ship date</param>
    /// <returns>True if requested shipdate falls under date range in agreement line</returns>
    public boolean validateRequestedShipDateWithAgreementLine(AgreementLine _agreementLine, SalesShippingDateRequested _shipRequested)
    {
        boolean ret = true;

        ret = (_agreementLine.EffectiveDate <= _shipRequested && _agreementLine.ExpirationDate >= _shipRequested);

        return ret;
    }

    /// <summary>
    /// Creates temporary sales order line buffer to get the matching agreement line.
    /// </summary>
    /// <param name = "_salesOrderLineV2Entity">Sales order line v2 entity buffer</param>
    /// <returns>Sales line</returns>
    private SalesLine createSalesLineTmp(SalesOrderLineV2Entity _salesOrderLineV2Entity)
    {
        SalesLine salesLine;
        InventDim inventDim;

        salesLine.setTmp();

        inventDim.inventSerialId    = _salesOrderLineV2Entity.ItemSerialNumber;
        inventDim.wMSLocationId     = _salesOrderLineV2Entity.ShippingWarehouseLocationId;
        inventDim.InventVersionId   = _salesOrderLineV2Entity.ProductVersionId;
        inventDim.InventStyleId     = _salesOrderLineV2Entity.ProductStyleId;
        inventDim.InventStatusId    = _salesOrderLineV2Entity.OrderedInventoryStatusId;
        inventDim.InventSizeId      = _salesOrderLineV2Entity.ProductSizeId;
        inventDim.InventSiteId      = _salesOrderLineV2Entity.ShippingSiteId;
        inventDim.InventLocationId  = _salesOrderLineV2Entity.ShippingWarehouseId;
        inventDim.InventColorId     = _salesOrderLineV2Entity.ProductColorId;
        inventDim.inventBatchId     = _salesOrderLineV2Entity.ItemBatchNumber;
        inventDim.configId          = _salesOrderLineV2Entity.ProductConfigurationId;

        inventDim = InventDim::findOrCreate(inventDim);

        salesLine.SalesId 						= _salesOrderLineV2Entity.SalesOrderNumber;
        salesLine.InventTransId 				= _salesOrderLineV2Entity.InventoryLotId;
        salesLine.SalesStatus 					= _salesOrderLineV2Entity.SalesOrderLineStatus;
        salesLine.Blocked 						= _salesOrderLineV2Entity.IsLineStopped;
        salesLine.CustomerLineNum 				= _salesOrderLineV2Entity.CustomersLineNumber;
        salesLine.DeliveryDateControlType 		= _salesOrderLineV2Entity.SalesOrderPromisingMethod;
        salesLine.DeliveryName 					= _salesOrderLineV2Entity.DeliveryAddressName;
        salesLine.DlvMode 						= _salesOrderLineV2Entity.DeliveryModeCode;
        salesLine.DlvTerm 						= _salesOrderLineV2Entity.DeliveryTermsId;
        salesLine.ExternalItemId 				= _salesOrderLineV2Entity.ExternalItemNumber;
        salesLine.ItemBOMId 					= _salesOrderLineV2Entity.BOMId;
        salesLine.ItemId 						= _salesOrderLineV2Entity.ItemNumber;
        salesLine.ItemRouteId 					= _salesOrderLineV2Entity.RouteId;
        salesLine.LineAmount 					= _salesOrderLineV2Entity.LineAmount;
        salesLine.LineDisc 						= _salesOrderLineV2Entity.LineDiscountAmount;
        salesLine.LinePercent 					= _salesOrderLineV2Entity.LineDiscountPercentage;
        salesLine.MultiLnDisc 					= _salesOrderLineV2Entity.MultilineDiscountAmount;
        salesLine.MultiLnPercent 				= _salesOrderLineV2Entity.MultilineDiscountPercentage;
        salesLine.Name 							= _salesOrderLineV2Entity.LineDescription;
        salesLine.OverDeliveryPct 				= _salesOrderLineV2Entity.AllowedOverdeliveryPercentage;
        salesLine.PackingUnit 					= _salesOrderLineV2Entity.PackingUnitSymbol;
        salesLine.PdsBatchAttribAutoRes 		= _salesOrderLineV2Entity.WillAutomaticInventoryReservationConsiderBatchAttributes;
        salesLine.PdsExcludeFromRebate 			= _salesOrderLineV2Entity.WillRebateCalculationExcludeLine;
        salesLine.PdsItemRebateGroupId 			= _salesOrderLineV2Entity.SalesRebateProductGroupId;
        salesLine.Port 							= _salesOrderLineV2Entity.IntrastatPortId;
        salesLine.PriceUnit 					= _salesOrderLineV2Entity.SalesPriceQuantity;
        salesLine.PurchorderFormNum 			= _salesOrderLineV2Entity.CustomerRequisitionNumber;
        salesLine.ReceiptDateConfirmed 			= _salesOrderLineV2Entity.ConfirmedReceiptDate;
        salesLine.ReceiptDateRequested 			= _salesOrderLineV2Entity.RequestedReceiptDate;
        salesLine.Reservation 					= _salesOrderLineV2Entity.InventoryReservationMethod;
        salesLine.SalesGroup 					= _salesOrderLineV2Entity.CommissionSalesRepresentativeGroupId;
        salesLine.SalesMarkup 					= _salesOrderLineV2Entity.FixedPriceCharges;
        salesLine.SalesPrice 					= _salesOrderLineV2Entity.SalesPrice;
        salesLine.SalesQty 						= _salesOrderLineV2Entity.OrderedSalesQuantity;
        salesLine.PdsCWQty 						= _salesOrderLineV2Entity.OrderedCatchWeightQuantity;
        salesLine.SalesUnit 					= _salesOrderLineV2Entity.SalesUnitSymbol;
        salesLine.ServiceOrderId 				= _salesOrderLineV2Entity.ServiceOrderNumber;
        salesLine.ShippingDateConfirmed 		= _salesOrderLineV2Entity.ConfirmedShippingDate;
        salesLine.ShippingDateRequested 		= _salesOrderLineV2Entity.RequestedShippingDate;
        salesLine.StatProcId 					= _salesOrderLineV2Entity.IntrastatStatisticsProcedureCode;
        salesLine.StatTriangularDeal 			= _salesOrderLineV2Entity.IsIntrastatTriangularDeal;
        salesLine.TaxGroup 						= _salesOrderLineV2Entity.SalesTaxGroupCode;
        salesLine.TaxItemGroup 					= _salesOrderLineV2Entity.SalesTaxItemGroupCode;
        salesLine.TransactionCode 				= _salesOrderLineV2Entity.IntrastatTransactionCode;
        salesLine.Transport 					= _salesOrderLineV2Entity.IntrastatTransportModeCode;
        salesLine.UnderDeliveryPct 				= _salesOrderLineV2Entity.AllowedUnderdeliveryPercentage;
        /* CB453_BackOrders field METAllowBackOrders deleted from SalesLine
        salesLine.METAllowBackOrders 			= _salesOrderLineV2Entity.METAllowBackOrders;*/
        salesLine.SalesDeliverNow 				= _salesOrderLineV2Entity.RevRecSalesDeliverNow;
        salesLine.OrderLineReference_NO 		= _salesOrderLineV2Entity.OrderLineReference;
        salesLine.RevRecContractStartDate 		= _salesOrderLineV2Entity.RevRecContractStartDate;
        salesLine.RevRecContractEndDate 		= _salesOrderLineV2Entity.RevRecContractEndDate;
        salesLine.RevRecOccurrences 			= _salesOrderLineV2Entity.RevRecOccurrences;
        salesLine.RevRecRevenueScheduleId 		= _salesOrderLineV2Entity.RevRecRevenueScheduleId;
        salesLine.InventoryServiceReservationId = _salesOrderLineV2Entity.InventoryServiceReservationId;
        salesLine.MpsFullRunCTPStatus 			= _salesOrderLineV2Entity.FullRunCTPStatus;
        salesLine.SalesDeliverNow 				= _salesOrderLineV2Entity.SalesDeliverNow;
        salesLine.SalesSalesOrderCreationMethod = _salesOrderLineV2Entity.SalesOrderLineCreationMethod;
        salesLine.OverrideSalesTax              = _salesOrderLineV2Entity.OverrideSalesTax;
        salesLine.PlanningPriority              = _salesOrderLineV2Entity.PlanningPriority;
        salesLine.CurrencyCode 					= _salesOrderLineV2Entity.CurrencyCode;
        salesLine.LineCreationSequenceNumber 	= _salesOrderLineV2Entity.LineCreationSequenceNumber;
        salesLine.LineNum 						= _salesOrderLineV2Entity.LineNumber;
        salesLine.TaxWithholdGroup 				= _salesOrderLineV2Entity.WithholdingTaxGroupCode;
        salesLine.EInvoiceAccountCode 			= _salesOrderLineV2Entity.EInvoiceDimensionAccountCode;
        salesLine.InventDimId 					= inventDim.inventDimId;

        return salesLine;
    }

    /// <summary>
    /// Parameter method to pass agreement line reference
    /// </summary>
    /// <param name = "_agreementLine">Agreement line reference</param>
    /// <returns>AgreementLine reference</returns>
    public AgreementLine parmAgreementLine(AgreementLine     _agreementLine = agreementLine)
    {
        agreementLine = _agreementLine;

        return agreementLine;
    }
